const COMPANY = 'KQuality Cleaning Services';
const SEGMENT_PITCH = {
  commercial_office: 'we help Adelaide offices keep their workspaces spotless so staff and clients always walk into a fresh, professional space',
  real_estate_strata: 'we support property and strata managers with dependable common-area, end-of-lease and vacate cleans across their portfolios',
  medical_childcare_gym: 'we provide compliance-grade cleaning and sanitisation for medical, childcare and fitness spaces where hygiene standards are non-negotiable',
  builders_construction: 'we handle post-construction and handover cleans so your sites are presentation-ready on deadline',
  hospitality_venues: 'we keep hospitality venues guest-ready with thorough after-service and overnight cleans',
  education_training: 'we help schools and learning centres maintain clean, healthy spaces for students and staff',
  retail_showrooms: 'we keep showrooms and retail floors presentation-perfect so your stock always looks its best'
};
const DEFAULT_PITCH = 'we provide reliable commercial cleaning for Adelaide businesses';
const ROLE_OK = /^(Owner|Co-?Owner|Director|Managing Director|CEO|Founder|Co-?Founder|Principal)$/i;
const NAME_BLOCK = /(Care|Quality|Executive|Nurse|Registered|Enrolled|General|Office|Property|Practice|Team|Group|Services)/i;
const AU_TAIL_RE = /,\s*Australia\s*$/i;
const STATE_RE = /\s+(SA|NSW|VIC|QLD|WA|NT|TAS|ACT)\s+\d{4}.*$/i;
const suburbOf = (r) => { if (r.suburb) return r.suburb; const a = (r.address || '').replace(AU_TAIL_RE, ''); const p = a.split(','); return p.length < 2 ? '' : p[p.length - 1].replace(STATE_RE, '').trim(); };
const bandOf = (s) => s == null ? 'cold' : (Number(s) >= 80 ? 'hot' : (Number(s) >= 55 ? 'warm' : 'cold'));
const clean = (t) => String(t || '').replace(/\s+/g, ' ').trim();
return $input.all().map(i => i.json).map(r => {
  const profile = r.profile || {};
  const band = bandOf(r.qualification_score);
  const suburb = suburbOf(r);
  const pitch = SEGMENT_PITCH[r.segment_code] || DEFAULT_PITCH;
  const people = Array.isArray(profile.people) ? profile.people : [];
  const person = people.find(p => p && ROLE_OK.test(String(p.role || '')) && /^[A-Z][a-z]{1,15} [A-Z][a-z]{1,20}$/.test(String(p.name || '')) && !NAME_BLOCK.test(String(p.name)));
  const firstName = person ? person.name.split(' ')[0] : null;
  const desc = clean(profile.description);
  return { json: {
    candidate_id: r.id,
    request: {
      business: {
        name: clean(r.business_name),
        industry: r.segment_name || null,
        location: suburb || clean(r.address) || null,
        description: desc || null
      },
      sender: { name: 'Michelle', company: COMPANY },
      contact_name: firstName,
      notes: 'qualification band: ' + band + '. segment pitch: ' + pitch + '. Local Adelaide team.'
    }
  } };
});

const BATCH_SIZE = 200;
const prev = $('Prepare AI Request').all();
const items = $input.all();
const drafts = [];
for (let i = 0; i < items.length; i++) {
  const res = items[i].json;
  if (!res || res.success !== true || !res.data || !res.data.email_body) continue;
  const src = prev[i] && prev[i].json;
  if (!src || !src.candidate_id) continue;
  drafts.push({
    candidate_id: src.candidate_id,
    subject: String(res.data.subject || ('Cleaning support for ' + src.request.business.name)).slice(0, 150),
    body: String(res.data.email_body),
    method: 'ai_' + res.capability + '_' + res.prompt_version
  });
}
const out = [];
for (let i = 0; i < drafts.length; i += BATCH_SIZE) { const chunk = drafts.slice(i, i + BATCH_SIZE); out.push({ json: { payload: JSON.stringify(chunk), batch_index: out.length, batch_count: chunk.length } }); }
if (!out.length) { out.push({ json: { payload: '[]', batch_index: 0, batch_count: 0 } }); }
return out;
